mapper.select:
select a.id, b.weight, d.warehouse_name as warehouseName, (select name from base_user_info where id = d.keeper) as keeper, d.grain_variety as grainVariety, d.grain_grade as grainGrade from task_flow a left join task_flow_weight_item b on a.id = b.task_id left join warehouse_out_order c on c.id = a.order_id left join sts_warehouse d on d.id = c.warehouse_id
b.weight_type = 2
and a.id = #{taskId}
